import{_ as e,o as s,c as t,a0 as n}from"./chunks/framework.t4Rf69I2.js";const k=JSON.parse('{"title":"密钥管理","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/key-management.md","filePath":"zh/guide/key-management.md","lastUpdated":1785233645000}'),i={name:"zh/guide/key-management.md"};function d(l,a,r,h,p,o){return s(),t("div",null,[...a[0]||(a[0]=[n(`<h1 id="密钥管理" tabindex="-1">密钥管理 <a class="header-anchor" href="#密钥管理" aria-label="Permalink to &quot;密钥管理&quot;">​</a></h1><p>本文介绍 go-cipher-cli 的密码转密钥和 Diceware 助记口令功能，以及它们与 <a href="https://tools.wcheer.com/" target="_blank" rel="noreferrer">web 工具</a> 的互通关系。</p><h2 id="核心能力" tabindex="-1">核心能力 <a class="header-anchor" href="#核心能力" aria-label="Permalink to &quot;核心能力&quot;">​</a></h2><h3 id="密码转密钥-enhance" tabindex="-1">密码转密钥（enhance） <a class="header-anchor" href="#密码转密钥-enhance" aria-label="Permalink to &quot;密码转密钥（enhance）&quot;">​</a></h3><p>将用户&quot;头脑记忆&quot;级别的密码，通过 Argon2id 慢函数加固 + HKDF-Expand(SHA-256) 域分离，转换成 256 位高熵密钥。<strong>真正用于加密/认证的是这把密钥</strong>，密码本身只是生成原料。</p><p>与 web 工具<strong>字节级互通</strong>：相同「密码 + 盐后缀」在 CLI 和 web 端会派生出完全相同的密钥。</p><h3 id="diceware-助记口令-diceware" tabindex="-1">Diceware 助记口令（diceware） <a class="header-anchor" href="#diceware-助记口令-diceware" aria-label="Permalink to &quot;Diceware 助记口令（diceware）&quot;">​</a></h3><p>用 EFF 大型词表（7776 词）和密码学安全随机掷骰，生成易记但高熵的口令。</p><h2 id="密码转密钥管线" tabindex="-1">密码转密钥管线 <a class="header-anchor" href="#密码转密钥管线" aria-label="Permalink to &quot;密码转密钥管线&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>密码 + 盐后缀</span></span>
<span class="line"><span>   │</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>1. 固定盐 = &quot;Your_Super_Long_Fixed_Salt_String_Here_2026&quot;</span></span>
<span class="line"><span>   全盐 = 固定盐 + 用户盐后缀</span></span>
<span class="line"><span>   │</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>2. Argon2id(64MB/3轮/1路并行, 输出 64 字节)</span></span>
<span class="line"><span>   → 主密钥 PRK (512 位)</span></span>
<span class="line"><span>   │</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>3. HKDF-Expand(SHA-256, PRK, domain=&quot;default-v1&quot;, 输出 32 字节)</span></span>
<span class="line"><span>   → 子密钥 (256 位)</span></span>
<span class="line"><span>   │</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>4. 输出 64 位 hex 字符串</span></span></code></pre></div><h3 id="固定盐" tabindex="-1">固定盐 <a class="header-anchor" href="#固定盐" aria-label="Permalink to &quot;固定盐&quot;">​</a></h3><p>第一层固定盐硬编码在代码中（<code>Your_Super_Long_Fixed_Salt_String_Here_2026</code>），与 web 端完全一致。它的作用是防止通用彩虹表——即使攻击者提前为所有常见密码构建了彩虹表，也会因为固定盐的存在而失效。</p><h3 id="盐后缀" tabindex="-1">盐后缀 <a class="header-anchor" href="#盐后缀" aria-label="Permalink to &quot;盐后缀&quot;">​</a></h3><p>用户可选的第二层盐（如站点名、设备名），与固定盐拼接后作为 Argon2id 的盐。不同盐后缀会派生出互不相同的密钥：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go-cipher-cli</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enhance</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;MyMaster@2024&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --salt-suffix</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> google</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 输出: 3aac7a86fd8c549020841738920154a05bcae6dd116c116a991144df33a440eb</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go-cipher-cli</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enhance</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;MyMaster@2024&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --salt-suffix</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> firefox</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 输出: 12a642320091c23fe4d1ba943c86ba9a60ad99f2eba6ce4814636a4cdd664e6d</span></span></code></pre></div><p>即使谷歌的密钥泄露，火狐的密钥也是安全的。</p><h3 id="hkdf-expand-域分离" tabindex="-1">HKDF-Expand 域分离 <a class="header-anchor" href="#hkdf-expand-域分离" aria-label="Permalink to &quot;HKDF-Expand 域分离&quot;">​</a></h3><p>Argon2id 输出的 64 字节主密钥 (PRK) 已经是均匀分布的高熵数据，因此跳过 HKDF-Extract，直接用纯 Expand 做域分离。内部 domain 标签固定为 <code>default-v1</code>。</p><h2 id="diceware-口令生成原理" tabindex="-1">Diceware 口令生成原理 <a class="header-anchor" href="#diceware-口令生成原理" aria-label="Permalink to &quot;Diceware 口令生成原理&quot;">​</a></h2><h3 id="eff-词表" tabindex="-1">EFF 词表 <a class="header-anchor" href="#eff-词表" aria-label="Permalink to &quot;EFF 词表&quot;">​</a></h3><p>使用 EFF（Electronic Frontier Foundation）发布的大型 Diceware 词表，共 7776 个英文单词，按 5 骰子骰点（11111–66666）的 base-6 编码顺序排列：</p><ul><li>骰点 <code>11111</code> → 下标 0 → <code>abacus</code></li><li>骰点 <code>11112</code> → 下标 1 → <code>abdomen</code></li><li>...</li><li>骰点 <code>66666</code> → 下标 7775 → <code>zoom</code></li></ul><h3 id="真随机掷骰" tabindex="-1">真随机掷骰 <a class="header-anchor" href="#真随机掷骰" aria-label="Permalink to &quot;真随机掷骰&quot;">​</a></h3><p>每词掷 5 次骰（1–6），每次骰点来自 Go 标准库 <code>crypto/rand</code>（操作系统 CSPRNG）。采用<strong>拒绝采样</strong>消除模偏差：</p><ul><li>生成随机字节（0–255）</li><li>只接受 0–251（6 的 42 倍），拒绝 252–255</li><li><code>byte % 6 + 1</code> 得到 1–6</li></ul><p>这确保了每个骰点的概率严格为 1/6，无偏向。</p><h3 id="熵值" tabindex="-1">熵值 <a class="header-anchor" href="#熵值" aria-label="Permalink to &quot;熵值&quot;">​</a></h3><table tabindex="0"><thead><tr><th>词数</th><th>信息熵</th><th>可能组合数</th><th>安全等级</th></tr></thead><tbody><tr><td>4</td><td>51.7 bit</td><td>3.66 × 10¹²</td><td>弱（不建议）</td></tr><tr><td>5</td><td>64.6 bit</td><td>2.84 × 10¹⁹</td><td>基础</td></tr><tr><td>6</td><td>77.5 bit</td><td>2.21 × 10²³</td><td>良好</td></tr><tr><td>7</td><td>90.5 bit</td><td>1.72 × 10²⁷</td><td>强</td></tr><tr><td>8</td><td>103.4 bit</td><td>1.34 × 10³¹</td><td>很强</td></tr></tbody></table><p>建议至少 5 个词。8 个词及以上适合对安全性要求极高的场景。</p><h2 id="安全说明" tabindex="-1">安全说明 <a class="header-anchor" href="#安全说明" aria-label="Permalink to &quot;安全说明&quot;">​</a></h2><h3 id="argon2id-抗暴力破解" tabindex="-1">Argon2id 抗暴力破解 <a class="header-anchor" href="#argon2id-抗暴力破解" aria-label="Permalink to &quot;Argon2id 抗暴力破解&quot;">​</a></h3><p>64MB 内存 / 3 轮迭代的参数使得每次派生耗时数秒，即便攻击者使用专用硬件也难以在有限时间内暴力破解。这是密码哈希竞赛 (PHC) 的获奖算法。</p><h3 id="全部本地运算" tabindex="-1">全部本地运算 <a class="header-anchor" href="#全部本地运算" aria-label="Permalink to &quot;全部本地运算&quot;">​</a></h3><p>密码和密钥始终在本地操作系统上运算，不会上传到任何服务器。</p><h3 id="确定性派生" tabindex="-1">确定性派生 <a class="header-anchor" href="#确定性派生" aria-label="Permalink to &quot;确定性派生&quot;">​</a></h3><p>同一组「密码 + 盐后缀」永远得到相同的密钥。无需保存密钥本身，只需记住密码即可随时还原。无法由密钥反推密码。</p><h2 id="与-web-工具的功能对照" tabindex="-1">与 web 工具的功能对照 <a class="header-anchor" href="#与-web-工具的功能对照" aria-label="Permalink to &quot;与 web 工具的功能对照&quot;">​</a></h2><table tabindex="0"><thead><tr><th>能力</th><th>CLI 命令</th><th>web 工具对应</th></tr></thead><tbody><tr><td>密码转密钥</td><td><code>enhance</code></td><td>密钥管理 → 密码转密钥</td></tr><tr><td>Diceware 助记口令</td><td><code>diceware</code></td><td>密钥管理 → Diceware 助记口令生成</td></tr></tbody></table><h2 id="技术细节" tabindex="-1">技术细节 <a class="header-anchor" href="#技术细节" aria-label="Permalink to &quot;技术细节&quot;">​</a></h2><h3 id="跨语言一致性保证" tabindex="-1">跨语言一致性保证 <a class="header-anchor" href="#跨语言一致性保证" aria-label="Permalink to &quot;跨语言一致性保证&quot;">​</a></h3><p>密码转密钥的 Go 实现通过了 6 组<strong>黄金向量测试</strong>：</p><ul><li>3 组不同 domain（age-key-v1 / file-key-v1 / auth-key-v1）</li><li>3 组不同密码 + 盐后缀组合（弱密码 / 强密码 / 中文密码）</li></ul><p>所有向量由 Go 参考实现生成，CLI 和 web 端都必须全部通过才算实现正确。</p><h3 id="完整测试覆盖" tabindex="-1">完整测试覆盖 <a class="header-anchor" href="#完整测试覆盖" aria-label="Permalink to &quot;完整测试覆盖&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./internal/...</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># internal/kdf: TestDeriveSubKeyByDomain_GoldenVectors (6 组向量)</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># internal/diceware: 词表完整性、骰点映射、口令生成、随机性、边界处理</span></span></code></pre></div>`,45)])])}const b=e(i,[["render",d]]);export{k as __pageData,b as default};
